/** The device-typed-messages pattern's reading, sent by a device program to the app. Generated here so the pattern's app side and device side compile against the class the Teleport compiler writes. */
export interface WeatherReport
{
    StationKey: string;
    StationId: string;
    Sequence: number;
    TemperatureC: number;
}

export const WEATHER_REPORT_VERSION = 1;
export const WEATHER_REPORT_OPCODE = 0x40000103;

const WEATHER_REPORT_STATION_ID_FIELD_ID = 0x38DC6D12;
const WEATHER_REPORT_STATION_KEY_FIELD_ID = 0x8D27A3DE;
const WEATHER_REPORT_TEMPERATURE_C_FIELD_ID = 0xE4D81F08;
const WEATHER_REPORT_SEQUENCE_FIELD_ID = 0xF25158D3;

export function createWeatherReport(init?: Partial<WeatherReport>): WeatherReport
{
    const instance = {} as WeatherReport;
    resetWeatherReport(instance);
    if (init)
    {
        Object.assign(instance, init);
    }
    return instance;
}

export function resetWeatherReport(target: WeatherReport): WeatherReport
{
    target.StationKey = '';
    target.StationId = '';
    target.Sequence = 0;
    target.TemperatureC = 0;
    return target;
}

export function encodeWeatherReport(value: WeatherReport): Uint8Array
{
    const writer = new TeleportObjectWriter(WEATHER_REPORT_VERSION);
    writeToTeleportWeatherReport(value, writer);
    return writer.finish();
}

export function writeToTeleportWeatherReport(instance: WeatherReport, scope: TeleportObjectWriter): void
{
    scope.writeStringField(WEATHER_REPORT_STATION_ID_FIELD_ID, instance.StationId);
    scope.writeStringField(WEATHER_REPORT_STATION_KEY_FIELD_ID, instance.StationKey);
    scope.writeFloat64Field(WEATHER_REPORT_TEMPERATURE_C_FIELD_ID, instance.TemperatureC);
    scope.writeInt32Field(WEATHER_REPORT_SEQUENCE_FIELD_ID, (instance.Sequence | 0));
}

export function decodeWeatherReport(data: ArrayBuffer | Uint8Array, destination?: WeatherReport): WeatherReport
{
    const reader = TeleportObjectReader.create(data);
    return readFromTeleportWeatherReport(reader, destination);
}

export function readFromTeleportWeatherReport(reader: TeleportObjectReader, destination?: WeatherReport): WeatherReport
{
    const instance = destination ?? createWeatherReport();
    resetWeatherReport(instance);
    readIntoWeatherReport(reader, instance);
    return instance;
}

function readIntoWeatherReport(reader: TeleportObjectReader, instance: WeatherReport): void
{
    let field: TeleportField | null;
    while ((field = reader.next()) !== null)
    {
        switch (field.fieldId)
        {
            case WEATHER_REPORT_STATION_ID_FIELD_ID:
            {
                if (field.isNull) throw new Error();
                instance.StationId = field.asString();
                break;
            }
            case WEATHER_REPORT_STATION_KEY_FIELD_ID:
            {
                if (field.isNull) throw new Error();
                instance.StationKey = field.asString();
                break;
            }
            case WEATHER_REPORT_TEMPERATURE_C_FIELD_ID:
            {
                if (field.isNull) throw new Error();
                instance.TemperatureC = field.asFloat64();
                break;
            }
            case WEATHER_REPORT_SEQUENCE_FIELD_ID:
            {
                if (field.isNull) throw new Error();
                instance.Sequence = field.asInt32();
                break;
            }
            default:
            {
                break;
            }
        }
    }
}

export function toProtocolMessageWeatherReport(value: WeatherReport, senderId: number, overrides?: ProtocolMessageOverrides): ProtocolMessage
{
    const payload = encodeWeatherReport(value);
    return createProtocolMessage(WEATHER_REPORT_OPCODE, payload, WEATHER_REPORT_VERSION, senderId, overrides);
}

export function fromProtocolMessageWeatherReport(raw: ProtocolMessage | ArrayBuffer | Uint8Array, destination?: WeatherReport): WeatherReport
{
    const payload = readProtocolMessagePayload(raw, WEATHER_REPORT_OPCODE, WEATHER_REPORT_VERSION);
    return decodeWeatherReport(payload, destination);
}

// Returns a Promise, which AppMessaging.send refuses. An AppMessageType takes toProtocolMessageWeatherReport above
export async function toProtocolMessageWeatherReportAsync(value: WeatherReport, senderId: number, overrides?: ProtocolMessageOverrides): Promise<ProtocolMessage>
{
    const payload = encodeWeatherReport(value);
    return createProtocolMessageAsync(WEATHER_REPORT_OPCODE, payload, WEATHER_REPORT_VERSION, senderId, overrides);
}

export async function fromProtocolMessageWeatherReportAsync(raw: ProtocolMessage | ArrayBuffer | Uint8Array, destination?: WeatherReport): Promise<WeatherReport>
{
    const payload = await readProtocolMessagePayloadAsync(raw, WEATHER_REPORT_OPCODE, WEATHER_REPORT_VERSION);
    return decodeWeatherReport(payload, destination);
}
